package com.bank.kill;

// The signals a real `kubectl describe pod` + events give you.
public class KillEvidence {
    final int exitCode;              // 137 for all SIGKILL cases
    final String lastStateReason;    // "OOMKilled" or "Error" or "Completed"
    final boolean livenessFailedBefore;
    final boolean sigtermThenKill;   // SIGTERM sent, then killed after grace
    final boolean duringDeploy;

    public KillEvidence(int exitCode, String reason, boolean liveness, boolean sigterm, boolean deploy) {
            this.exitCode = exitCode;
            this.lastStateReason = reason;
            this.livenessFailedBefore = liveness;
            this.sigtermThenKill = sigterm
            this.duringDeploy = deploy;
    }
}
