package com.bank.kill;

import java.util.logging.Logger;

public class KillClassifier {
    private static final Logger log = Logger.getLogger(KillClassifier.class.getName());

    public String classify(KillEvidence e) {
            if (e.exitCode != 137) { log.info(() -> "exit " + e.exitCode + " not a SIGKILL case");
            return "OTHER"; }
        log.info("exit 137 = 128 + signal 9 (SIGKILL) — force-killed, reason unknown from number alone");

        if ("OOMKilled".equals(e.lastStateReason)) {
            log.severe("classify: OOMKILL (Last State Reason=OOMKilled, breached memory limit)");
            log.info("FIX: right-size memory limit above peak + -XX:MaxRAMPercentage; if leak, profile & fix");
            return "OOMKILL";
        }
        if (e.livenessFailedBefore) {
            log.severe("classify: LIVENESS_KILL (Liveness probe failed events before restart)");
            log.info("FIX: trivial liveness endpoint, loosen threshold/timeout; fix real hang/deadlock");
            return "LIVENESS_KILL";
        }
        if (e.sigtermThenKill && e.duringDeploy) {
            log.severe("classify: GRACE_TIMEOUT (SIGTERM then SIGKILL after grace, during deploy)");
            log.info("FIX: handle SIGTERM to drain, raise terminationGracePeriodSeconds, add preStop");
            return "GRACE_TIMEOUT";
        }
        log.warning("classify: UNKNOWN 137 — inspect events timeline further");
        return "UNKNOWN";
    }
}
