package com.bank.kill;

import java.math.BigDecimal;
import java.util.logging.Logger;

// Models SIGTERM handling: drain in-flight transfer within the grace window.
public class GracefulShutdown {
    private static final Logger log = Logger.getLogger(GracefulShutdown.class.getName());

    // returns true if drained cleanly, false if SIGKILLed (exit 137) due to overrun
    public boolean onSigterm(int drainSeconds, int graceSeconds, Account from, Account to, BigDecimal amount) {
        log.info(() -> "SIGTERM received: stop intake, drain in-flight (" + drainSeconds
                + "s) within grace " + graceSeconds + "s");
        if (drainSeconds <= graceSeconds) {
            from.debit(amount); to.credit(amount);
            log.info(() -> "drained: transfer " + from.getAccountId() + "->" + to.getAccountId()
                    + " Rs." + amount + " committed, clean exit 0");
            return true;
        }
        log.severe("drain overran grace -> SIGKILL (exit 137), in-flight transfer cut off");
        return false;
    }
}
