package com.bank.kill;

import java.math.BigDecimal;
import java.util.logging.*;

public class Exit137Demo {
    private static final Logger log = Logger.getLogger(Exit137Demo.class.getName());
    static {
        LogManager.getLogManager().reset();
        ConsoleHandler h = new ConsoleHandler(); h.setFormatter(new BankLogFormatter()); h.setLevel(Level.ALL);
        Logger root = Logger.getLogger(""); root.addHandler(h); root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        Account rajesh = new Account("SAV2001", "Rajesh Kumar", new BigDecimal("1000000"));
        Account priya  = new Account("CUR3001", "Priya Sharma", new BigDecimal("250000"));
        KillClassifier c = new KillClassifier();

        // Day 1: OOMKill
        c.classify(new KillEvidence(137, "OOMKilled", false, false, false));
        // Day 2: liveness kill
        c.classify(new KillEvidence(137, "Error", true, false, false));
        // Day 3: grace timeout during deploy
        c.classify(new KillEvidence(137, "Error", false, true, true));

        // Graceful shutdown: grace too short -> SIGKILL; then fixed grace -> clean drain
        GracefulShutdown gs = new GracefulShutdown();
        gs.onSigterm(40, 30, rajesh, priya, new BigDecimal("50000"));   // overrun -> 137
        gs.onSigterm(20, 60, rajesh, priya, new BigDecimal("50000"));   // drains clean
    }
}
